/**
 * Creates a household; the creator is auto-added as the first member.
 * @summary Create a household
 */
export const createHousehold = async (userId: string,
    createHouseholdRequest?: CreateHouseholdRequest, options?: Parameters<typeof customFetch>[1]): Promise<createHouseholdResponse> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Array.isArray(h)) return Object.fromEntries(h);
    return h;
  };
return customFetch<createHouseholdResponse>(getCreateHouseholdUrl(userId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(createHouseholdRequest)
  }
);}



